hints:
```
build adjacency list from invocations
suspicious = DFS/BFS from k following outgoing edges
canRemove = true
for each edge (a, b):
    if not suspicious[a] and suspicious[b]:
        canRemove = false
if canRemove:
    return all methods not in suspicious
else:
    return all methods 0..n-1
```

code.cpp:
class Solution {
public:
    vector<int> remainingMethods(int n, int k, vector<vector<int>>& invocations) {
        vector<vector<int>> adj(n);
        for (auto& inv : invocations) {
            adj[inv[0]].push_back(inv[1]);
        }

        // Find all suspicious methods reachable from k
        vector<bool> suspicious(n, false);
        vector<int> stk;
        stk.push_back(k);
        suspicious[k] = true;
        while (!stk.empty()) {
            int u = stk.back();
            stk.pop_back();
            for (int v : adj[u]) {
                if (!suspicious[v]) {
                    suspicious[v] = true;
                    stk.push_back(v);
                }
            }
        }

        // Check if any non-suspicious method invokes a suspicious one
        bool canRemove = true;
        for (auto& inv : invocations) {
            if (!suspicious[inv[0]] && suspicious[inv[1]]) {
                canRemove = false;
                break;
            }
        }

        vector<int> result;
        if (canRemove) {
            for (int i = 0; i < n; i++) {
                if (!suspicious[i]) {
                    result.push_back(i);
                }
            }
        } else {
            result.reserve(n);
            for (int i = 0; i < n; i++) {
                result.push_back(i);
            }
        }
        return result;
    }
};
